%[text] # Plotting 3D Energyscape Example
%[text] This example shows how to view a 3D acoustic image (range, azimuth and elevation) as a point cloud or as isosurfaces with `clait.plot3DEnergyscape`.
%[text] ## Setup scene and sensor
structScene = struct();
structScene.targetAzimuth   = [0  -30   25   40  -15];
structScene.targetElevation = [0   15  -20   25  -30];
structScene.targetRange     = [1.5 2.2  1.8  2.8  2.5];
structScene.targetStrength  = [1   1    1    1    1];
structScene.speedOfSound = 343;

structSensor = struct();
structSensor.sampleRate = 450e3;
structSensor.emissionSignal = clait.fm_sweep(80e3, 20e3, structSensor.sampleRate, 2, 1, 10);
structSensor.coordinatesEmitter = [0 0 0.05];
structSensor.numSamplesSensor = 15000;
structSensor.coordinatesMicrophones = [0 -0.0384 0.0151; 0 -0.0232 0.0101; 0 -0.0121 0.0164; 0 -0.0046 0.0153; ...
                                       0 -0.0367 0.0054; 0 -0.0144 0.0061; 0 0.0054 0.0011; 0 0.0273 -0.0027; ...
                                       0 -0.0387 0.0001; 0 -0.0281 0.0002; 0 -0.0094 -0.0013; 0 -0.0060 -0.0000; ...
                                       0 -0.0357 -0.0117; 0 -0.0318 -0.0112; 0 -0.0286 -0.0166; 0 0.0029 -0.0086; ...
                                       0 -0.0011 0.0178; 0 0.0067 0.0115; 0 0.0103 0.0144; 0 0.0172 0.0140; ...
                                       0 0.0384 0.0022; 0 0.0283 0.0162; 0 0.0354 0.0125; 0 0.0373 0.0150; ...
                                       0 -0.0084 -0.0047; 0 0.0107 -0.0111; 0 0.0189 -0.0166; 0 0.0363 -0.0101; ...
                                       0 0.0057 -0.0224; 0 -0.0036 -0.0223; 0 0.0315 -0.0161; 0 0.0083 -0.0178];
%%
%[text] ## Setup imaging
%[text] A 3D image needs directions in azimuth and elevation. Here nearly uniform equal-area directions with 2 degree spacing within a 60 degree cone around the sensor axis are used.
structImage = struct();
[structImage.directionsAzimuth, structImage.directionsElevation] = ...
    clait.generateDirections('equalarea', struct('spacing', 2, 'coneAngle', 60));
structImage.numDirections = numel(structImage.directionsAzimuth);
structImage.lowpassFreq = 5e3;
structImage.doEnvelope = 1;
structImage.doThresholdAtZero = 1;
structImage.decimationFactor = 10;
structImage.matchedFilterMethod = 'Normal';
structImage.matchedFilterFreq = [20e3 80e3];
structImage.doMatchedFilter = 1;
structImage.methodImaging = 'DMAS3';
structImage.coherenceType = 'CF';
structImage.methodProcessing = 'mexcuda';
%%
%[text] ## Generate microphone data and acoustic image
dataMicrophones = clait.simulateMicrophoneData(structScene, structSensor);
dataMicrophones = dataMicrophones + 0.01 * randn(size(dataMicrophones));
image3D = clait.calculateAcousticImage(dataMicrophones, structSensor, structImage);
%%
%[text] ## Query all options
opts = clait.plot3DEnergyscape('options');
%%
%[text] ## Example 1: Point cloud
%[text] Every range bin of every direction within 30 dB of the peak becomes a point. Louder points are larger and more opaque, which gives the cloud a volumetric look. Rotate the figure to look around.
figure('Position', [100 100 800 600]); %[output:25d4f263]
opts = clait.plot3DEnergyscape('options');
opts.title = 'Point cloud, 30 dB';
clait.plot3DEnergyscape(image3D, structSensor, structImage, opts); %[output:25d4f263]
%%
%[text] ## Example 2: Isosurfaces
%[text] The image is resampled on a voxel grid and drawn as nested semi-transparent surfaces at -6, -12 and -20 dB.
figure('Position', [100 100 800 600]); %[output:2b6f80a0]
opts = clait.plot3DEnergyscape('options');
opts.renderMode = 'isosurface';
opts.isoLevels = [-6 -12 -20];
opts.title = 'Isosurfaces at -6, -12 and -20 dB';
clait.plot3DEnergyscape(image3D, structSensor, structImage, opts); %[output:2b6f80a0]
%%
%[text] ## Example 3: Narrow dB window and range limits
%[text] A smaller dB window shows only the strongest reflections, and `rangeLimits` hides everything outside a range interval, here 1.6 m to 3 m.
figure('Position', [100 100 800 600]); %[output:770fe788]
opts = clait.plot3DEnergyscape('options');
opts.dbCut = -15;
opts.rangeLimits = [1.6 3];
opts.markerSize = 30;
opts.title = 'Point cloud, 15 dB, range 1.6 m to 3 m';
clait.plot3DEnergyscape(image3D, structSensor, structImage, opts); %[output:770fe788]

